5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.escalation.DailyRegistrationLimitException;
8	
9	/**
10	 * Rejects a create-owner request once the maximum number of owners ({@value #DAILY_LIMIT})
11	 * have already been registered on the current date, responding 429 via
12	 * {@link DailyRegistrationLimitException}. Owners are counted by their
13	 * {@link Owner#getRegistrationDate() registrationDate} matching today.
14	 */
15	public class RequireDailyRegistrationCapacity {
16	
17	    /** Maximum owners that may be registered on a single date; the request is rejected once reached. */
18	    static final int DAILY_LIMIT = 100;
19	
20	    public void service(OwnerRepository ownerRepository) throws DailyRegistrationLimitException {
21	        LocalDate today = LocalDate.now();
22	        long registeredToday = ownerRepository.findAll().stream()
23	            .map(Owner::getRegistrationDate)
24	            .filter(today::equals)
25	            .count();
26	        if (registeredToday >= DAILY_LIMIT) {
27	            throw new DailyRegistrationLimitException(DAILY_LIMIT);
28	        }
29	    }
30	}
